// Native stages of the packed forwarding image compiler.
//
//   ATLAS n start length hop ...   -> maximal forwarding runs of one RIB
//   PACK R N A ...                 -> exact FIDX v2 image plus packed lookups
//   TRACE A image address ...      -> packed lookups inside an existing image
//   PLAN ...                       -> globally optimal layouts of a case
//
// Every stage reads one whitespace delimited ASCII request through EOF and
// writes its token sequence to stdout.
#include "engine.hpp"
#include "planner.hpp"

#include <iostream>
#include <string>
#include <vector>

namespace {

void stage_atlas() {
    size_t n;
    std::cin >> n;
    std::vector<Route> fib;
    fib.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        std::string s;
        int length, hop;
        std::cin >> s >> length >> hop;
        fib.push_back(make_route(s, length, hop));
    }
    std::vector<Run> runs = build_runs(fib);
    std::cout << runs.size() << '\n';
    for (std::size_t i = 0; i < runs.size(); ++i)
        std::cout << hexkey(runs[i].start) << ' ' << runs[i].hop << '\n';
}

void stage_pack() {
    size_t r, n, a;
    std::cin >> r >> n >> a;
    std::vector<Key> starts, addresses;
    std::vector<int> hops;
    for (size_t i = 0; i < r; ++i) {
        std::string s;
        int hop;
        std::cin >> s >> hop;
        starts.push_back(key(s));
        hops.push_back(hop);
    }
    std::vector<Layout> nodes;
    for (size_t i = 0; i < n; ++i) {
        Layout node;
        size_t b;
        std::cin >> node.lo >> node.span >> node.mode >> node.cached >> b;
        for (size_t j = 0; j < b; ++j) {
            int c;
            std::cin >> c;
            node.children.push_back(c);
        }
        nodes.push_back(node);
    }
    for (size_t i = 0; i < a; ++i) {
        std::string s;
        std::cin >> s;
        addresses.push_back(key(s));
    }
    PackedResult result = pack_image(starts, hops, nodes, addresses);
    std::cout << result.image << '\n';
    for (std::size_t i = 0; i < result.answers.size(); ++i) {
        const Answer& ans = result.answers[i];
        std::cout << ans.hop << ' ' << ans.run << ' ' << ans.path.size();
        for (std::size_t p = 0; p < ans.path.size(); ++p) std::cout << ' ' << ans.path[p];
        std::cout << '\n';
    }
}

void stage_trace() {
    size_t n;
    std::string image;
    std::cin >> n >> image;
    std::vector<Key> addresses;
    for (size_t i = 0; i < n; ++i) {
        std::string s;
        std::cin >> s;
        addresses.push_back(key(s));
    }
    std::vector<Answer> answers = trace_image(image, addresses);
    for (std::size_t i = 0; i < answers.size(); ++i) {
        const Answer& ans = answers[i];
        std::cout << ans.hop << ' ' << ans.run << ' ' << ans.path.size();
        for (std::size_t p = 0; p < ans.path.size(); ++p) std::cout << ' ' << ans.path[p];
        std::cout << '\n';
    }
}

// PLAN reads the compiled runs of every version of one case together with the
// burst workload and returns the globally optimal layouts.
void stage_plan() {
    size_t nv;
    int cache_pages, hit, miss, d0, d1, d2;
    std::cin >> nv >> cache_pages >> hit >> miss >> d0 >> d1 >> d2;
    int decode[3] = {d0, d1, d2};
    std::vector<planner::Version> versions;
    for (size_t v = 0; v < nv; ++v) {
        planner::Version ver;
        int runs;
        std::cin >> runs;
        ver.runs = runs;
        for (int i = 0; i < runs; ++i) {
            std::string s;
            std::cin >> s;
            ver.starts.push_back(key(s));
        }
        for (int i = 0; i < runs; ++i) {
            int hop;
            std::cin >> hop;
            ver.hops.push_back(hop);
        }
        size_t nb;
        std::cin >> nb;
        for (size_t b = 0; b < nb; ++b) {
            int repeat, count;
            std::cin >> repeat >> count;
            ver.rep.push_back(repeat);
            std::vector<Key> addrs;
            for (int i = 0; i < count; ++i) {
                std::string s;
                std::cin >> s;
                addrs.push_back(key(s));
            }
            ver.addrs.push_back(addrs);
        }
        versions.push_back(ver);
    }
    planner::Result result = planner::solve_case(versions, cache_pages, hit, miss, decode);
    std::cout << result.work << ' ' << result.pages << '\n';
    std::cout << result.versions.size() << '\n';
    for (std::size_t v = 0; v < result.versions.size(); ++v) {
        const std::vector<planner::Node>& nodes = result.versions[v];
        std::cout << nodes.size() << '\n';
        for (std::size_t i = 0; i < nodes.size(); ++i) {
            const planner::Node& n = nodes[i];
            std::cout << n.lo << ' ' << n.span << ' ' << n.mode << ' ' << n.cached << ' '
                      << n.children.size();
            for (std::size_t c = 0; c < n.children.size(); ++c) std::cout << ' ' << n.children[c];
            std::cout << '\n';
        }
    }
}

}  // namespace

int main() {
    try {
        std::string command;
        if (!(std::cin >> command)) throw std::runtime_error("native command");
        if (command == "ATLAS") {
            stage_atlas();
        } else if (command == "PACK") {
            stage_pack();
        } else if (command == "TRACE") {
            stage_trace();
        } else if (command == "PLAN") {
            stage_plan();
        } else {
            throw std::runtime_error("unknown native command");
        }
        if (!std::cin) throw std::runtime_error("truncated native input");
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
    std::cout.flush();
    return 0;
}
